const enfermedadData=[{"disease":"Los correos de treinta padres quedaron visibles para todos","characteristic":"Se usó el campo Para en vez de copia oculta","opts":["Se usó el campo Para en vez de copia oculta","El servidor de correo falló","Alguien reenvió el mensaje","La lista estaba desactualizada"]},{"disease":"Se perdió un teléfono y con él la base de datos entera","characteristic":"La copia de seguridad estaba sin cifrar","opts":["La copia de seguridad estaba sin cifrar","El teléfono no tenía patrón","La base era demasiado grande","Faltaba respaldo en la nube"]},{"disease":"Una familia pidió borrar los datos de su hija y no se pudo","characteristic":"Nunca hubo inventario: no se sabía dónde estaba cada dato","opts":["Nunca hubo inventario: no se sabía dónde estaba cada dato","La petición llegó tarde","El sistema no tiene botón de borrar","Los datos eran necesarios"]},{"disease":"Salieron a internet las caras de una sección entera","characteristic":"Se publicó con el permiso de la maestra y no de las familias","opts":["Se publicó con el permiso de la maestra y no de las familias","La foto tenía mala calidad","Se publicó en la red equivocada","Faltó etiquetar el centro"]},{"disease":"Una empresa terminó con datos de uso de menores","characteristic":"Se aceptó una función gratis a cambio de datos identificables","opts":["Se aceptó una función gratis a cambio de datos identificables","La empresa incumplió el contrato","Los datos se enviaron por error","Faltó leer los términos"]},{"disease":"Nadie supo qué hacer el día que se filtró algo","characteristic":"El plan de incidente no estaba escrito antes","opts":["El plan de incidente no estaba escrito antes","La filtración fue muy grande","No había quién respondiera el teléfono","Se descubrió demasiado tarde"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

