const identifyTaskDB=[{"s":"Permite llegar a una persona concreta.","type":"Dato que identifica"},{"s":"Habla de un grupo y no señala a nadie.","type":"Dato agregado"},{"s":"El para qué, escrito en una línea.","type":"Finalidad"},{"s":"Quedarse con el mínimo de campos que sirve.","type":"Minimización"},{"s":"Quién puede ver el dato, con nombre y cargo.","type":"Control de acceso"},{"s":"La fecha con la que el dato se elimina.","type":"Plazo de borrado"},{"s":"Cambiar el nombre por un código que otro traduce.","type":"Seudonimización"},{"s":"Lo que se hace si algo se filtra, escrito antes.","type":"Plan de incidente"},{"s":"La lista de todo lo que el proyecto guarda de otros.","type":"Inventario de datos"},{"s":"El permiso que da la familia, no el menor.","type":"Consentimiento"}];
const classifyTaskDB=[{"w":"Nombre y apellido","gen":"Dato","n":"Persona","g":"Identifica","t":"Llega a alguien concreto"},{"w":"22 de sexto completaron","gen":"Dato","n":"Grupo","g":"Agregado","t":"No señala a nadie"},{"w":"Correo de la madre","gen":"Dato","n":"Persona","g":"Identifica","t":"Llega a alguien concreto"},{"w":"Tres centros activos","gen":"Dato","n":"Grupo","g":"Agregado","t":"No señala a nadie"},{"w":"Grado y fecha para medir uso","gen":"Cantidad","n":"Justa","g":"Mínimo","t":"Cumple la finalidad"},{"w":"Fecha de nacimiento completa","gen":"Cantidad","n":"Sobra","g":"De más","t":"No hace falta para nada"},{"w":"Cifrar el respaldo","gen":"Efecto","n":"Protege","g":"Baja el riesgo","t":"Menos superficie expuesta"},{"w":"Mandar la lista por WhatsApp","gen":"Efecto","n":"Expone","g":"Sube el riesgo","t":"Copias que no se controlan"},{"w":"Fecha de borrado escrita","gen":"Efecto","n":"Protege","g":"Baja el riesgo","t":"El dato no se queda para siempre"},{"w":"Guardar por si acaso","gen":"Efecto","n":"Expone","g":"Sube el riesgo","t":"Sin finalidad no hay límite"}];
const completeTaskDB=[{"s":"El dato que llega a una persona concreta es el que ___.","opts":["identifica","agrega","resume"],"ans":"identifica"},{"s":"El dato que habla de un grupo es el dato ___.","opts":["agregado","personal","privado"],"ans":"agregado"},{"s":"Quedarse con lo mínimo que sirve es ___.","opts":["minimizar","cifrar","agregar"],"ans":"minimizar"},{"s":"El permiso de un menor lo da su ___.","opts":["familia","escuela","maestra"],"ans":"familia"},{"s":"Todo dato nace con fecha de ___.","opts":["borrado","copia","revisión"],"ans":"borrado"},{"s":"Cambiar el nombre por un código es ___.","opts":["seudonimizar","minimizar","agregar"],"ans":"seudonimizar"},{"s":"Con menores, la duda se resuelve hacia el ___.","opts":["no","sí","después"],"ans":"no"},{"s":"Lo que no se guarda no se puede ___.","opts":["perder","medir","usar"],"ans":"perder"}];
const explainQuestions=[{"q":"Explica la diferencia entre dato que identifica y dato agregado, y por qué casi todo se puede resolver con el segundo.","ans":"El dato que identifica permite llegar a una persona concreta: nombre y apellido, correo, teléfono, foto, o la combinación de escuela, grado y sección, que juntas también señalan. El agregado habla de un grupo: «22 estudiantes de sexto completaron la misión en marzo». Casi todas las peticiones que llegan «con nombres» buscan en realidad saber si algo funcionó, y para eso el conteo sirve igual y no crea una copia más de datos personales. La pregunta educada cuando alguien insiste es: qué vas a hacer con los nombres que no puedas hacer con el conteo."},{"q":"¿Qué es minimizar y cómo se aplica al nombre en la constancia de una misión?","ans":"Minimizar es quedarse con el mínimo de campos que todavía cumple la finalidad: se van quitando campos hasta que la finalidad deja de cumplirse y se para justo antes. En la constancia, la finalidad es que el estudiante vea su nombre en un papel bonito, y para eso basta el nombre de pila, escrito por él en el momento. Ni siquiera hace falta que ese dato salga del teléfono: si se arma la constancia en el aparato, el proyecto no se entera y no tiene nada que proteger. El dato que nunca viaja a un servidor es el único que no se puede filtrar desde el servidor."},{"q":"¿Quién autoriza el uso de datos o fotos de un menor, y qué límites tiene esa autorización?","ans":"Un menor no autoriza: autoriza su madre, su padre o quien lo tenga a cargo. Y la autorización es para algo concreto, no un permiso general para siempre: que una familia acepte que su hija salga en el mural del aula no significa que acepte verla en una publicación pública de internet, y eso hay que preguntarlo por separado. Además, quien autorizó puede cambiar de opinión: si pide que se borre, se borra, se confirma por escrito con la fecha y no se le pregunta el motivo."},{"q":"Una empresa ofrece añadir gratis una función de IA a cambio de los datos de uso de los estudiantes. ¿Qué se contesta y con qué condición?","ans":"Mete una función vistosa y saca datos de menores hacia una empresa sobre la que el proyecto no manda y a la que las familias nunca autorizaron nada. Y lo que sale no se puede traer de vuelta. La condición con la que sí: datos agregados y sin identificadores, con un documento que diga qué reciben exactamente, para qué y por cuánto tiempo. Si eso no les sirve, la respuesta es no y no pasa nada: una función vistosa vale menos que la confianza de una maestra, que es lo que sostiene el proyecto."},{"q":"Se perdió un teléfono que tenía el respaldo de la base de datos. ¿Qué falló y qué se hace?","ans":"Falló olvidar que la copia de seguridad es un sitio más donde vive el dato: se protege el servidor y se deja el respaldo sin cifrar, y entonces es la base entera regalada, con el agravante de que nadie se entera de que se la llevaron. Lo que hay que tener escrito de antemano: dónde viven las copias, con qué clave están cifradas y quién la tiene. Y el plan de incidente empieza siempre igual: cambiar las claves de todo lo que ese aparato podía abrir, antes de averiguar nada más; después, saber qué datos salieron y de cuántas personas, avisar a las familias afectadas sin adornos, y escribir qué se cambió."},{"q":"Escribe la política de una página de este proyecto: sus cinco puntos y por qué cada uno.","ans":"1) Qué se guarda: la lista completa de campos, sin «etcétera», porque lo que no está en la lista es lo que nadie revisa. 2) Para qué: una línea concreta por dato, porque «por si acaso» es como se acumula lo que después se filtra. 3) Quién lo ve: con nombre y cargo, no «el equipo», porque si no se puede nombrar a la persona es que nadie responde por eso. 4) Cuánto tiempo: una fecha o condición de borrado desde el primer día, porque un dato sin caducidad se queda para siempre. 5) Qué se hace si se filtra: a quién se avisa, en qué orden y en cuánto tiempo, escrito antes, porque el día que pasa nadie está en condiciones de improvisar."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

