function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un centro pide que M.E.T.A.S guarde las calificaciones de sus estudiantes para llevar el registro del año escolar."},{"txt":"Sale una foto muy buena de una sección trabajando con las misiones y la maestra dice que se puede publicar."},{"txt":"Hay que avisar de una actividad a treinta familias y se prepara un correo con todas las direcciones."},{"txt":"La aplicación pide el nombre del estudiante para personalizar la constancia y se plantea guardarlo en el servidor."},{"txt":"Una empresa ofrece añadir gratis una función de inteligencia artificial a cambio de recibir los datos de uso de los estudiantes."},{"txt":"Un maestro pide el listado con nombres de quiénes de su sección entraron a las misiones esta semana."},{"txt":"El respaldo de la base de datos estaba sin clave en un teléfono que se quedó en un bus."},{"txt":"Una madre escribe pidiendo que se borre todo lo que el proyecto tenga de su hija."}];
const critCaseQuestions=["1. ¿Qué datos se están pidiendo o guardando exactamente, y quién responde por ellos?","2. ¿Con qué mínimo se cumple la misma finalidad?","3. Escribe en 3-4 frases lo que contestarías, por escrito.","4. ¿Cuándo se borra, quién lo ve y qué pasa si se filtra?"];
const critCaseGuides=["Nombrar los campos uno por uno, sin «etcétera». Y ojo con quién responde: aceptar datos es aceptar responder por ellos, aunque el que los pidió sea otro.","Casi siempre basta el conteo agregado, un identificador que traduce la escuela, o un dato que se queda en el aparato. El mínimo se busca quitando campos hasta que la finalidad deja de cumplirse.","La respuesta se escribe, no se manda a la carrera. Y casi ninguna petición se rechaza entera: se contesta con lo que sí se puede dar, que suele resolver lo mismo.","Sin fecha de borrado, sin dueño de acceso con nombre y sin plan de incidente, el dato no está guardado: está esperando."];

const critErrorBank=[{"txt":"\"Se lo mando con nombres, total es la maestra de esos niños\".","g1":"Aunque la relación sea legítima, cada copia de una lista con nombres es un sitio más del que se puede filtrar, y las copias no se vigilan.","g2":"Se pregunta qué va a hacer con la lista. Si es para saber si la actividad funcionó, el conteo por grado le sirve igual y no crea la copia."},{"txt":"\"La maestra dio permiso para la foto, así que se puede publicar\".","g1":"El permiso que hace falta lo da la familia de cada niño que salga, y para esa publicación concreta.","g2":"La foto de las manos y la pantalla cumple lo mismo sin necesitar permiso de nadie. Si la cara aporta algo que la mano no, entonces se pide autorización por escrito, una por niño."},{"txt":"\"Guardamos también la fecha de nacimiento y la dirección, por si hacen falta\".","g1":"Sin finalidad escrita no hay límite, y así es como se acumula lo que después se filtra.","g2":"Se quitan campos hasta que la finalidad deje de cumplirse. Lo que no se guarda no se puede perder ni hay que protegerlo."},{"txt":"\"El respaldo lo tengo en el teléfono, que siempre ando conmigo\".","g1":"La copia contiene lo mismo que la base de datos, y sin cifrar es la base entera regalada. Además, si se pierde, nadie se entera de que se la llevaron.","g2":"Se escribe dónde viven las copias, con qué clave están cifradas y quién la tiene. Y el plan de incidente empieza por cambiar las claves de todo lo que ese aparato abría."},{"txt":"\"La función de IA es gratis, solo quieren datos de uso\".","g1":"Los datos de uso de menores salen hacia una empresa sobre la que el proyecto no manda y a la que las familias no autorizaron nada.","g2":"Datos agregados y sin identificadores, con un documento que diga qué reciben, para qué y por cuánto tiempo. Si eso no les sirve, no hay trato."},{"txt":"\"Se filtró algo pequeño, mejor no alarmar a nadie\".","g1":"Una filtración contada a tiempo se perdona; una descubierta después, no. Y las familias tienen derecho a saber qué salió.","g2":"Se avisa, se dice qué datos salieron y de cuántas personas, y se escribe qué se cambió para que no se repita. Ocultarlo cuesta más que contarlo."}];

const critDecisionBank=["Un centro quiere que M.E.T.A.S guarde las notas de sus menores: ¿qué se acepta guardar y qué se devuelve al centro?","Hay una foto buenísima de una sección usando las misiones: ¿qué se publica y con qué permiso?","Aviso a treinta familias por correo: ¿cómo se manda para que no sea una filtración?","La constancia necesita el nombre del estudiante: ¿dónde se guarda ese dato y por qué?","Una empresa ofrece IA gratis a cambio de datos de uso: ¿qué se contesta y con qué condición?","Un maestro pide el listado con nombres de su sección: ¿qué se le manda?","Se perdió el teléfono con el respaldo sin cifrar: ¿cuál es el primer paso y en qué orden siguen los demás?","Una familia pide borrar todo lo de su hija: ¿qué se hace y qué demuestra este caso?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: se identifica quién firma, quién traba y quién paga antes de responder; se empieza pequeño y reversible; nunca se compromete a terceros que no firmaron; la autoría y el uso se acuerdan antes de entregar, no después; y todo queda por escrito con la institución y no con la persona. Cuando la oferta es grande y urgente, esa combinación es justamente la señal para tomarse los días que hagan falta y responder con una condición concreta.";

const critCompareBank=[{"a":"Guardar un identificador que la escuela sabe traducir.","b":"Guardar el nombre y apellido de cada estudiante.","ga":"Caso A: se puede medir y contar igual, y aun con toda la base robada no se sabe de quién es cada fila.","gb":"Caso B: cualquier fuga expone a personas concretas, y el que responde por eso pasa a ser el proyecto."},{"a":"Publicar la foto de las manos y la pantalla.","b":"Publicar la foto del grupo mirando a la cámara.","ga":"Caso A: enseña que se usa de verdad y no necesita permiso de nadie.","gb":"Caso B: necesita autorización escrita de la familia de cada niño, para esa publicación concreta."},{"a":"Armar la constancia en el teléfono con lo que el usuario escribió.","b":"Guardar el nombre completo en el servidor para la constancia.","ga":"Caso A: el dato nunca viaja, así que no se puede filtrar desde el servidor ni hay que responder por él.","gb":"Caso B: se crea una base de nombres de menores para resolver algo que se resolvía sin ella."},{"a":"Contestar a una petición de datos al día siguiente y por escrito.","b":"Mandar el archivo por WhatsApp el mismo día que lo piden.","ga":"Caso A: da tiempo a ver si el conteo cumple lo mismo y deja registro de qué se envió.","gb":"Caso B: el archivo sale y ya no vuelve: queda en su teléfono, en su nube y en el grupo al que lo reenvíe."}];

const critCauseBank=[{"cause":"Se guardan datos sin escribir para qué.","guide":"Sin finalidad no hay límite: se acumula «por si acaso» y lo acumulado es exactamente lo que se filtra."},{"cause":"Se manda un listado con nombres por un canal que deja copias.","guide":"El archivo ya no vuelve. Queda en el teléfono de quien lo recibe, en su nube y en cualquier grupo al que lo reenvíe."},{"cause":"Se publica una foto con caras con el permiso de la maestra.","guide":"El permiso que hacía falta era el de cada familia, y para esa publicación concreta. Lo que sirve para el mural del aula no sirve para internet."},{"cause":"El respaldo se guarda sin cifrar.","guide":"La copia contiene lo mismo que la base. Un aparato perdido se convierte en la base de datos entera, y sin aviso."},{"cause":"Ningún dato tiene fecha de borrado.","guide":"Todo se queda para siempre, y llega el día en que se hereda una base que nadie sabe qué contiene ni por qué."},{"cause":"No hay inventario de datos.","guide":"El día que una familia pide un borrado no se puede cumplir, porque nadie sabe dónde está cada dato de esa persona."}];
const critEffectBank=[{"effect":"Una petición de borrado se cumplió en el mismo día.","guide":"Había inventario: se sabía dónde estaba cada dato de esa persona. Ese es el examen real del sistema."},{"effect":"Se perdió un teléfono y no salió ningún dato.","guide":"El respaldo estaba cifrado y el aparato no era el único sitio. La copia también es un sitio, y estaba tratada como tal."},{"effect":"La escuela quedó conforme sin recibir ningún nombre.","guide":"El conteo agregado cumplía la misma finalidad. Casi todas las peticiones «con nombres» se resuelven así."},{"effect":"Se publicó la actividad sin pedir un solo permiso.","guide":"La foto era de manos y pantalla. Cuando la cara no aporta nada que no aporte la mano, no hay que pedir nada."},{"effect":"Una filtración pequeña no dañó la confianza de las familias.","guide":"Se avisó el mismo día, se dijo qué salió y qué se cambió. Contarlo a tiempo es lo que la salva."},{"effect":"El proyecto pudo decir que no a una empresa sin quedar mal.","guide":"Había una política de una página escrita de antes. Con la regla en la mano, el no es de la norma y no es personal."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La petición que llega · Forma ${cf} · Los datos de los demás · Ruta de la Casa Cerrada`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Los datos de los demás, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La petición que llega: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Los datos de los demás, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La petición que llega Los datos de los demás · Ruta de la Casa Cerrada · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La petición que llega · Los datos de los demás · Ruta de la Casa Cerrada · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La petición que llega · Los datos de los demás · Ruta de la Casa Cerrada · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🪪","label":"Qué dato es","text":"¿<strong>Identifica</strong> a alguien o habla de un grupo? <strong>Decide:</strong> todo lo demás. <strong>Se rompe:</strong> al olvidar que escuela, grado y sección juntos también señalan. <strong>En M.E.T.A.S:</strong> el conteo por grado no identifica; el nombre sí."},{"y":"2","icon":"🎯","label":"Para qué se pide","text":"La <strong>finalidad</strong>, en una línea concreta. <strong>Decide:</strong> si el dato se pide o no. <strong>Se rompe:</strong> con «por si acaso» y «para estadísticas». <strong>En M.E.T.A.S:</strong> saber si una misión funcionó, que se resuelve sin nombres."},{"y":"3","icon":"✂️","label":"El mínimo","text":"El <strong>menor número de campos</strong> que cumple la finalidad. <strong>Decide:</strong> cuánto hay que proteger después. <strong>Se rompe:</strong> al pedir el formulario completo por costumbre. <strong>En M.E.T.A.S:</strong> grado y fecha bastan."},{"y":"4","icon":"👀","label":"Quién lo ve","text":"El <strong>control de acceso</strong>, con nombre y cargo. <strong>Decide:</strong> quién responde. <strong>Se rompe:</strong> con «el equipo» o «los maestros». <strong>En M.E.T.A.S:</strong> si no se puede nombrar a la persona, nadie está respondiendo."},{"y":"5","icon":"⏱️","label":"Cuánto se guarda","text":"La <strong>fecha o condición de borrado</strong>, puesta el primer día. <strong>Decide:</strong> que no se quede para siempre. <strong>Se rompe:</strong> al no ponerla nunca. <strong>En M.E.T.A.S:</strong> al terminar el año escolar."},{"y":"6","icon":"📝","label":"Quién autoriza","text":"Con menores, <strong>la familia</strong>, y para un uso concreto. <strong>Decide:</strong> si se puede usar. <strong>Se rompe:</strong> al tomar el permiso de la maestra como si fuera el de la familia. <strong>En M.E.T.A.S:</strong> una autorización por niño y por publicación."},{"y":"7","icon":"🚨","label":"Si se filtra","text":"El <strong>plan de incidente</strong>, escrito antes. <strong>Decide:</strong> cuánto daño hace. <strong>Se rompe:</strong> improvisando el día que pasa. <strong>En M.E.T.A.S:</strong> cortar accesos, ver qué salió, avisar y escribir qué se cambió."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>Pediste 24 horas:</strong> la presión se corta en seco y la conversación pasa del sentimiento a los números.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Al día siguiente decides tú:</strong> si el plazo era real, la oferta sigue en pie y ahora con condiciones tuyas. Si se cayó, la presión era el producto.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Contestaste en caliente:</strong> el sí salió con la emoción alta y sin comparar nada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔗</span><span class="ms-text"><strong>Y la coherencia lo amarra:</strong> ese sí pequeño se cobra después con uno más grande. No fue tonto: fue una decisión tomada en el peor momento posible.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"minimo":{"nombre":"El mínimo necesario","icon":"✂️","estructura":{"title":"Qué es","info":"• El <strong>menor número de campos</strong> que cumple la finalidad<br>• Se busca quitando, no añadiendo<br>• Lo que no se guarda no se puede perder ni hay que protegerlo"},"funcion":{"title":"Cómo se decide","info":"• Se escribe la finalidad en una línea<br>• Se quitan campos hasta que <strong>deja de cumplirse</strong><br>• Se para justo antes de ese punto y se anota por qué"},"enfermedades":{"title":"Dónde se rompe","info":"• Al copiar un formulario completo por costumbre<br>• Con el «por si acaso» y el «para estadísticas»<br>• Al pedir fecha de nacimiento o dirección sin usarlas nunca"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Para medir uso bastan <strong>grado y fecha</strong><br>• Para la constancia basta el <strong>nombre de pila</strong>, en el teléfono<br>• Para el centro, un identificador que <strong>solo la escuela traduce</strong>"}},"acceso":{"nombre":"Quién lo ve","icon":"👀","estructura":{"title":"Qué es","info":"• La lista de <strong>quién puede ver cada dato</strong><br>• Se escribe con nombre y cargo, no por grupos<br>• Si no se puede nombrar a la persona, nadie responde por eso"},"funcion":{"title":"Cómo se decide","info":"• Por defecto, <strong>nadie</strong>: se abre solo lo que hace falta<br>• Cada acceso tiene un motivo escrito<br>• Se revisa cuando alguien cambia de rol o se va"},"enfermedades":{"title":"Dónde se rompe","info":"• Con accesos que se dan «temporalmente» y se quedan<br>• Cuando el archivo se manda por WhatsApp y ya no se controla<br>• Con la tabla que tiene la seguridad por fila desactivada"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Cada copia enviada es <strong>un acceso más que no se vigila</strong><br>• Regla: el conteo por defecto, la lista solo si hace falta<br>• Y se apunta en Destellos qué se envió, a quién y cuándo"}},"plazo":{"nombre":"Cuánto se guarda","icon":"⏱️","estructura":{"title":"Qué es","info":"• La <strong>fecha o condición de borrado</strong> de cada dato<br>• Se pone el día que el dato entra, no después<br>• Un dato sin caducidad se queda para siempre"},"funcion":{"title":"Cómo se decide","info":"• Se mira la finalidad: cuando se cumple, el dato sobra<br>• Se elige una fecha concreta o un hecho claro<br>• Se revisa el inventario <strong>una vez al año</strong> y se borra lo vencido"},"enfermedades":{"title":"Dónde se rompe","info":"• Con los respaldos, que conservan lo ya borrado<br>• Con las copias sueltas en teléfonos y correos<br>• Cuando el proyecto cambia de manos y nadie sabe qué hay"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Lo del año escolar se borra <strong>al cerrar el año</strong><br>• Los respaldos también caducan, no solo la base<br>• El simulacro del caso 8 se hace <strong>una vez al año</strong>"}},"incidente":{"nombre":"Si se filtra","icon":"🚨","estructura":{"title":"Qué es","info":"• El plan de <strong>qué se hace cuando algo sale</strong><br>• Escrito antes, porque ese día nadie improvisa bien<br>• Incluye a quién se avisa, en qué orden y en cuánto tiempo"},"funcion":{"title":"Cómo se decide","info":"• Primero <strong>cortar el acceso</strong>: cambiar claves de todo lo que abría<br>• Después saber qué salió y de cuántas personas<br>• Avisar a las familias afectadas, sin adornos, y escribir qué se cambió"},"enfermedades":{"title":"Dónde se rompe","info":"• Al querer averiguar todo antes de cortar el acceso<br>• Al decidir «no alarmar» y que se descubra después<br>• Al no dejar registro, y repetir el mismo fallo el año siguiente"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Casos reales que hay que prever: <strong>teléfono perdido</strong> con respaldo, correo con copias visibles, APK compartido con una clave dentro<br>• Regla: <strong>ocultarlo cuesta más que contarlo</strong>"}}};
let labParte='centro',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🛡️ ¡'+name+' completó la Etapa 1 de la Ruta de la Casa Cerrada (Los datos de los demás)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

// ===================== INIT =====================
window.addEventListener('DOMContentLoaded',()=>{
  initTheme();
  loadProgress();
  initTimeline();
  upFC();
  buildQz();
  showQz();
  buildClass();
  showId();
  showCmp();
  updateRetoButtons();
  buildRoute();
  showNeuron();
  showNeuro();
  showEnfer();
  updateLabDisplay();
  document.querySelector('[data-parte="web"]')?.classList.add('active-pri');
  document.querySelector('[data-aspecto="estructura"]')?.classList.add('active-sec');
  renderAchPanel();
});
